+		t.Fatalf("expected 1 run, got %d", len(report.Runs))
+	}
+	if report.Runs[0].Tool.Driver.Name != "test-scanner" {
+		t.Errorf("unexpected driver name: %s", report.Runs[0].Tool.Driver.Name)
+	}
+}
