+	}
+	if summary.Medium != 1 {
+		t.Errorf("Medium: want 1, got %d", summary.Medium)
+	}
+	if summary.Low != 1 {
+		t.Errorf("Low: want 1, got %d", summary.Low)
+	}
+	if summary.Info != 1 {
+		t.Errorf("Info: want 1, got %d", summary.Info)
