+			},
+			"results": [{
+				"ruleId": "tool-poisoning",
+				"level": "error",
+				"message": {"text": "Tool description contains hidden instructions targeting Claude"},
+				"locations": [{
+					"physicalLocation": {
+						"artifactLocation": {"uri": "mcp_config.json"},
