+						"artifactLocation": {"uri": "tools/search.py"},
+						"region": {"startLine": 42, "startColumn": 5}
+					}
+				}]
+			}]
+		}]
+	}`)
+
+	report, err := ParseSARIF(data)
+	if err != nil {
+		t.Fatalf("ParseSARIF: %v", err)
