+	// Second finding: warning level
+	if findings[1].Severity != SeverityMedium {
+		t.Errorf("f1 severity: expected %q, got %q", SeverityMedium, findings[1].Severity)
+	}
+
+	// Third finding: note level
+	if findings[2].Severity != SeverityLow {
