+}
+
+// NewService creates a new SecurityService
+func NewService(storage Storage, registry *Registry, docker *DockerRunner, dataDir string, logger *zap.Logger) *Service {
+	engine := NewEngine(docker, registry, dataDir, logger)
+	return &Service{
+		storage:  storage,
+		engine:   engine,
+		registry: registry,
+		docker:   docker,
