+// helper to create a service with test registry and mock storage
+func newTestService(t *testing.T) (*Service, *mockStorage, *mockEmitter) {
+	t.Helper()
+	logger := zap.NewNop()
+	store := newMockStorage()
+	docker := NewDockerRunner(logger)
+	registry := &Registry{
