+func (s *Server) handleScanAll(w http.ResponseWriter, r *http.Request) {
+	if !s.requireSecurity(w, r) {
+		return
+	}
+
+	// Parse optional request body
+	var req struct {
+		ScannerIDs []string `json:"scanner_ids"`
+	}
